        "task": "قم بكتابة موديول برمجي متكامل في Node.js ينفذ منطق (إرسال البريد الإلكتروني والإشعارات) وفق أفضل الممارسات؛ مع تطبيق المعالجة غير المتزامنة، التحقق من المدخلات، وإدارة الأخطاء بأمان.",
